package com.fixmer.mared.technology.workspace.live122;
import com.fixmer.mared.gui2.framework.screen.MaredScreen;
import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.network.chat.Component;
import java.util.*;
/** Vertical player list: invite/remove and independent rights controls on each row. */
public final class WorkspaceMembers122 extends MaredScreen {
    private final WorkspaceScreen122 previous;private Map<String,String> data;private EditBox query;private String filter="",notice="";private int page;private long refreshAt;private List<Player> visible=List.of();
    private record Player(String id,String name,String role,boolean member,boolean pending,boolean online){}
    public WorkspaceMembers122(WorkspaceScreen122 previous,Map<String,String> data){super(WorkspaceScreen122.tr("section_members"));this.previous=previous;this.data=data;}
    private Button button(Component text,int x,int y,int w,Runnable action){return addRenderableWidget(WorkspaceButton131.builder(text,b->action.run()).bounds(x,y,w,20).build());}
    private static final List<String> LIST_FIELDS=List.of("memberNames131","online","members","pending131","role");
    private int contentWidth(){return Math.max(1,Math.min(850,width-24));}
    private void refresh(){
        if(previous.available())previous.send("VIEW",Map.of(),next->{
            if(!"OK".equals(next.get("result"))){notice=next.getOrDefault("result","");return;}
            boolean changed=LIST_FIELDS.stream().anyMatch(key->!Objects.equals(next.get(key),data.get(key)));
            data=next;
            // Periodic refreshes must not replace focused widgets when the list is unchanged.
            if(changed&&minecraft.screen==this)rebuildWidgets();
        });
    }
    private void applyFilter(){filter=query.getValue();page=0;rebuildWidgets();}
    @Override protected void init(){previous.attachClient();String input=query==null?filter:query.getValue();int w=contentWidth(),x=(width-w)/2;
        int searchButtonWidth=Math.min(104,Math.max(20,w/3));
        query=addRenderableWidget(new EditBox(font,x,42,Math.max(1,w-searchButtonWidth-6),20,WorkspaceScreen122.tr("player_search131")));
        query.setValue(input);query.setHint(WorkspaceScreen122.tr("player_search131"));
        button(WorkspaceScreen122.tr("find_players131"),x+w-searchButtonWidth,42,searchButtonWidth,this::applyFilter);
        var names=new HashMap<String,String>();var online=new HashSet<String>();for(String row:data.getOrDefault("memberNames131","").split("\n")){String[] p=row.split("\\|",2);if(p.length==2)names.put(p[0],p[1]);}for(String row:data.getOrDefault("online","").split("\n")){String[] p=row.split("\\|",2);if(p.length==2){names.put(p[0],p[1]);online.add(p[0]);}}
        var roles=new HashMap<String,String>();var pending=new HashSet<String>();for(String row:data.getOrDefault("members","").split("\n")){String[] p=row.split("\\|",2);if(p.length==2)roles.put(p[0],p[1]);}for(String row:data.getOrDefault("pending131","").split("\n")){String[] p=row.split("\\|",2);if(p.length==2){pending.add(p[0]);names.putIfAbsent(p[0],p[0]);}}
        var ids=new HashSet<>(names.keySet());ids.addAll(roles.keySet());visible=ids.stream().map(id->new Player(id,names.getOrDefault(id,id),roles.getOrDefault(id,""),roles.containsKey(id),pending.contains(id),online.contains(id))).filter(p->p.name().toLowerCase(Locale.ROOT).contains(filter.toLowerCase(Locale.ROOT))).sorted(Comparator.comparing(Player::member).reversed().thenComparing(Player::name,String.CASE_INSENSITIVE_ORDER)).toList();
        int rows=Math.max(1,(height-140)/38);int rightsWidth=w<300?30:76;page=Math.min(page,Math.max(0,(visible.size()-1)/rows));boolean owner="OWNER".equals(data.get("role"));for(int n=0;n<rows&&page*rows+n<visible.size();n++){Player player=visible.get(page*rows+n);int y=78+n*38;var membership=button(Component.literal(player.member()?"−":"+"),x+w-rightsWidth-36,y,30,()->toggle(player));membership.active=owner&&!player.role().equals("OWNER")&&!player.pending();membership.setTooltip(Tooltip.create(WorkspaceScreen122.tr(player.member()?"revoke":player.pending()?"invite_pending131":"invite131")));var rights=button(w<300?Component.literal("…"):WorkspaceScreen122.tr("permissions131"),x+w-rightsWidth,y,rightsWidth,()->permissions(player));rights.active=owner&&!player.role().equals("OWNER");rights.setTooltip(Tooltip.create(WorkspaceScreen122.tr("permissions131")));}
        button(Component.literal("<"),x,height-56,40,()->{page--;rebuildWidgets();}).active=page>0;button(Component.literal(">"),x+w-40,height-56,40,()->{page++;rebuildWidgets();}).active=(page+1)*rows<visible.size();button(WorkspaceScreen122.tr("back"),x,height-28,w,this::onClose);
    }
    private void toggle(Player p){if(!previous.available())return;if(p.member())previous.send("VIEW",Map.of(),fresh->previous.send("MEMBER",Map.of("target",p.id(),"role","NONE","prefix","","deny","","hidden","","rev",fresh.get("revision")),this::changed));else if(p.pending())previous.send("CANCEL_INVITE131",Map.of("target",p.id()),this::changed);else previous.send("INVITE131",Map.of("target",p.id(),"role","DEVELOPER","prefix","","deny","","hidden",""),this::changed);}
    private void changed(Map<String,String> d){notice=d.getOrDefault("result","");if(d.containsKey("revision"))data=d;rebuildWidgets();}
    private void permissions(Player player){if(!previous.available())return;previous.send("RIGHTS131",Map.of("target",player.id()),rights->{if(!"OK".equals(rights.get("result")))return;var form=new TreeMap<>(rights);form.put("targetName131",player.name());form.put("pending131",Boolean.toString(player.pending()));if(!player.member())form.put("submitLabel131",player.pending()?"update_invite131":"invite_with_rights131");minecraft.setScreen(new WorkspacePermissions131(this,form,fields->{if(!previous.available())return;if(fields.containsKey("cancel131")){previous.send("CANCEL_INVITE131",Map.of("target",player.id()),d->{minecraft.setScreen(this);changed(d);});return;}previous.send("VIEW",Map.of(),fresh->{boolean member=fresh.getOrDefault("members","").lines().anyMatch(row->row.startsWith(player.id()+"|"));var q=new TreeMap<>(fields);q.put("target",player.id());if(member)q.put("rev",fresh.get("revision"));previous.send(member?"MEMBER":"INVITE131",q,d->{minecraft.setScreen(this);changed(d);});});},previous::tickClient));});}
    @Override public boolean keyPressed(int key,int scan,int mods){if((key==257||key==335)&&query!=null&&query.isFocused()){applyFilter();return true;}return super.keyPressed(key,scan,mods);}
    @Override public void tick(){previous.tickClient();if(!previous.panelAllowed131("MEMBERS")){minecraft.setScreen(previous);return;}long now=System.nanoTime();if(now-refreshAt>2_000_000_000L&&query!=null&&!query.isFocused()&&previous.available()){refreshAt=now;refresh();}}@Override public void onClose(){minecraft.setScreen(previous);}@Override public boolean isPauseScreen(){return false;}
    @Override public void render(GuiGraphics g,int mx,int my,float dt){g.fill(0,0,width,height,com.fixmer.mared.technology.editor.GenesisEditorVisuals.bg());g.drawCenteredString(font,title,width/2,12,com.fixmer.mared.technology.editor.GenesisEditorVisuals.text());int w=contentWidth(),x=(width-w)/2,nameWidth=Math.max(1,w-(w<300?78:124)),rows=Math.max(1,(height-140)/38);for(int n=0;n<rows&&page*rows+n<visible.size();n++){var p=visible.get(page*rows+n);int y=78+n*38;g.fill(x,y-3,x+w,y+30,n%2==0?com.fixmer.mared.technology.editor.GenesisEditorVisuals.panel():com.fixmer.mared.technology.editor.GenesisEditorVisuals.raised());g.drawString(font,font.plainSubstrByWidth(p.name(),nameWidth),x+8,y,com.fixmer.mared.technology.editor.GenesisEditorVisuals.text(),false);String state=p.member()?WorkspaceScreen122.tr("role."+p.role()).getString():WorkspaceScreen122.tr(p.pending()?"invite_pending131":"not_member131").getString();g.drawString(font,font.plainSubstrByWidth(state+(p.online()?" · online":""),nameWidth),x+8,y+14,com.fixmer.mared.technology.editor.GenesisEditorVisuals.dim(),false);}super.render(g,mx,my,dt);if(!notice.isBlank())g.drawCenteredString(font,WorkspaceScreen122.tr("status."+notice),width/2,height-48,com.fixmer.mared.technology.editor.GenesisEditorVisuals.warn());}
}
